    here = os.path.dirname(os.path.abspath(__file__))
    for code, vals in T.items():
        assert len(vals) == len(KEYS), code
        p = os.path.join(here, "i18n", f"{code}.json")
        d = json.load(open(p, encoding="utf-8"))
        d.update(dict(zip(KEYS, vals)))
        d["page.identity.title"] = d["nav.brand"]
        d["page.privacy.title"] = d["nav.privacy"]
        d["page.terms.title"] = d["nav.terms"]
        json.dump(d, open(p, "w", encoding="utf-8"), ensure_ascii=False, indent=0, sort_keys=True)
    print(len(T), "bahasa diperbarui")
